package com.betternotifications;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class DangerLevelTest
{
	@Test
	public void dangerStartsAtWarningThreshold()
	{
		assertEquals(0, DangerLevel.calculate(40, 100, 40, 15), 0.0001);
	}

	@Test
	public void dangerReachesMaximumAtCriticalThreshold()
	{
		assertEquals(1, DangerLevel.calculate(15, 100, 40, 15), 0.0001);
		assertEquals(1, DangerLevel.calculate(1, 100, 40, 15), 0.0001);
	}

	@Test
	public void dangerScalesBetweenThresholds()
	{
		assertEquals(0.5, DangerLevel.calculate(30, 200, 40, 20), 0.0001);
	}

	@Test
	public void detectsCriticalAmount()
	{
		assertTrue(DangerLevel.isCritical(15, 100, 15));
		assertFalse(DangerLevel.isCritical(16, 100, 15));
		assertFalse(DangerLevel.isCritical(0, 0, 15));
	}

	@Test
	public void criticalThresholdAlwaysStaysBelowWarningThreshold()
	{
		assertEquals(39, DangerLevel.effectiveCriticalAmount(40, 80));
		assertEquals(0, DangerLevel.effectiveCriticalAmount(1, 1));
		assertEquals(15, DangerLevel.effectiveCriticalAmount(40, 15));
	}

	@Test
	public void idleDangerFadesBetweenNotificationAndCriticalTimes()
	{
		assertEquals(0, DangerLevel.calculateElapsed(3_000_000_000L, 3, 7), 0.0001);
		assertEquals(0.5, DangerLevel.calculateElapsed(5_000_000_000L, 3, 7), 0.0001);
		assertEquals(1, DangerLevel.calculateElapsed(7_000_000_000L, 3, 7), 0.0001);
	}

	@Test
	public void idleCriticalTimeAlwaysFollowsNotificationTime()
	{
		assertEquals(6, DangerLevel.effectiveCriticalSeconds(5, 3));
		assertEquals(10, DangerLevel.effectiveCriticalSeconds(5, 10));
	}
}

