package com.betternotifications;

final class DangerLevel
{
	private DangerLevel()
	{
	}

	static double calculate(int current, int maximum, int warningAmount, int criticalAmount)
	{
		if (maximum <= 0 || current < 0)
		{
			return 0;
		}

		int warning = Math.max(1, warningAmount);
		int critical = effectiveCriticalAmount(warning, criticalAmount);
		return clamp((warning - current) / (double) (warning - critical));
	}

	static boolean isCritical(int current, int maximum, int criticalAmount)
	{
		return maximum > 0 && current >= 0 && current <= criticalAmount;
	}

	static int effectiveCriticalAmount(int warningAmount, int criticalAmount)
	{
		return Math.max(0, Math.min(criticalAmount, Math.max(1, warningAmount) - 1));
	}

	static double calculateElapsed(long elapsedNanos, int notificationSeconds, int criticalSeconds)
	{
		long notificationNanos = Math.max(1, notificationSeconds) * 1_000_000_000L;
		long criticalNanos = effectiveCriticalSeconds(notificationSeconds, criticalSeconds) * 1_000_000_000L;
		return clamp((elapsedNanos - notificationNanos) / (double) (criticalNanos - notificationNanos));
	}

	static int effectiveCriticalSeconds(int notificationSeconds, int criticalSeconds)
	{
		return Math.max(Math.max(1, notificationSeconds) + 1, criticalSeconds);
	}

	private static double clamp(double value)
	{
		return Math.max(0, Math.min(1, value));
	}
}

package com.betternotifications;

import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.Paint;
import java.awt.RadialGradientPaint;
import java.awt.Rectangle;
import java.awt.geom.Point2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

final class BetterNotificationsOverlay extends Overlay
{
	private static final double MIN_VISIBLE_DANGER = 0.002;
	private static final double PULSE_PERIOD_MILLIS = 1100.0;
	private static final double ENHANCED_GLOW_INTENSITY = 0.35;

	private final BetterNotificationsPlugin plugin;
	private final BetterNotificationsConfig config;

	private double displayedHitpointsDanger;
	private double displayedPrayerDanger;
	private double displayedIdleDanger;
	private long lastFrameNanos;

	@Inject
	private BetterNotificationsOverlay(
		BetterNotificationsPlugin plugin,
		BetterNotificationsConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.UNDER_WIDGETS);
		setPriority(PRIORITY_HIGH);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		updateAnimation();
		double danger = Math.max(Math.max(displayedHitpointsDanger, displayedPrayerDanger), displayedIdleDanger);
		if (danger < MIN_VISIBLE_DANGER)
		{
			return null;
		}

		Rectangle bounds = graphics.getClipBounds();
		if (bounds == null || bounds.width <= 0 || bounds.height <= 0)
		{
			return null;
		}

		Color color = blendColors(
			config.hitpointsColor(), displayedHitpointsDanger,
			config.prayerColor(), displayedPrayerDanger,
			config.idleColor(), displayedIdleDanger);
		double pulse = getPulseMultiplier();
		double intensity = Math.min(1, danger * pulse);
		int depth = Math.max(1, (int) Math.round(
			Math.min(bounds.width, bounds.height)
				* config.maximumInsetPercent() / 100.0 * (0.25 + 0.75 * danger)));
		int alpha = (int) Math.round(color.getAlpha()
			* config.maximumOpacityPercent() / 100.0 * intensity);

		drawEdgeWarning(graphics, bounds, depth,
			new Color(color.getRed(), color.getGreen(), color.getBlue(), clampAlpha(alpha)));
		drawEnhancedGlows(graphics, bounds, depth, pulse);
		return null;
	}

	void reset()
	{
		displayedHitpointsDanger = 0;
		displayedPrayerDanger = 0;
		displayedIdleDanger = 0;
		lastFrameNanos = 0;
	}

	private void updateAnimation()
	{
		long now = System.nanoTime();
		if (lastFrameNanos == 0)
		{
			lastFrameNanos = now;
		}

		double elapsedMillis = Math.min(100, (now - lastFrameNanos) / 1_000_000.0);
		lastFrameNanos = now;
		double smoothing = Math.max(1, config.smoothingMilliseconds());
		double interpolation = 1 - Math.exp(-elapsedMillis / smoothing);
		displayedHitpointsDanger += (plugin.getHitpointsDanger() - displayedHitpointsDanger) * interpolation;
		displayedPrayerDanger += (plugin.getPrayerDanger() - displayedPrayerDanger) * interpolation;
		displayedIdleDanger += (plugin.getIdleDanger() - displayedIdleDanger) * interpolation;
	}

	private void drawEnhancedGlows(Graphics2D graphics, Rectangle bounds, int depth, double pulse)
	{
		if (displayedHitpointsDanger >= MIN_VISIBLE_DANGER)
		{
			drawEnhancedGlow(graphics, bounds, depth, config.hitpointsColor(),
				Math.min(1, displayedHitpointsDanger * pulse), true);
		}
		if (displayedPrayerDanger >= MIN_VISIBLE_DANGER)
		{
			drawEnhancedGlow(graphics, bounds, depth, config.prayerColor(),
				Math.min(1, displayedPrayerDanger * pulse), false);
		}
		if (displayedIdleDanger >= MIN_VISIBLE_DANGER)
		{
			drawEnhancedGlow(graphics, bounds, depth, config.idleColor(),
				Math.min(1, displayedIdleDanger * pulse), false);
		}
	}

	private void drawEnhancedGlow(
		Graphics2D graphics, Rectangle bounds, int depth, Color color, double intensity, boolean hitpoints)
	{
		double detail = ENHANCED_GLOW_INTENSITY * intensity;
		if (detail <= 0)
		{
			return;
		}

		Paint oldPaint = graphics.getPaint();
		Composite oldComposite = graphics.getComposite();

		Color shadow = new Color(
			Math.max(0, color.getRed() / 5),
			Math.max(0, color.getGreen() / 5),
			Math.max(0, color.getBlue() / 5),
			clampAlpha((int) Math.round(125 * detail)));
		drawOuterAnchor(graphics, bounds, Math.max(3, depth / 5), shadow);

		drawResourceAura(graphics, bounds, depth, color, detail, hitpoints);

		graphics.setPaint(oldPaint);
		graphics.setComposite(oldComposite);
	}

	private static void drawOuterAnchor(Graphics2D graphics, Rectangle bounds, int depth, Color edge)
	{
		drawEdgeWarning(graphics, bounds, depth, edge);
	}

	private static void drawResourceAura(
		Graphics2D graphics, Rectangle bounds, int depth, Color color, double detail, boolean hitpoints)
	{
		double strength = hitpoints ? 0.2 : 0.24;
		graphics.setComposite(AlphaComposite.SrcOver.derive((float) Math.min(1, strength * detail)));
		int radius = Math.max(2, (int) Math.round(depth * 1.35));
		Color center = new Color(
			Math.min(255, color.getRed() + (hitpoints ? 35 : 95)),
			Math.min(255, color.getGreen() + (hitpoints ? 55 : 80)),
			Math.min(255, color.getBlue() + (hitpoints ? 15 : 35)),
			145);
		Color middle = new Color(color.getRed(), color.getGreen(), color.getBlue(), 55);
		Color transparent = new Color(color.getRed(), color.getGreen(), color.getBlue(), 0);

		drawCornerAura(graphics, bounds.x, bounds.y, radius, center, middle, transparent);
		drawCornerAura(graphics, bounds.x + bounds.width, bounds.y, radius, center, middle, transparent);
		drawCornerAura(graphics, bounds.x, bounds.y + bounds.height, radius, center, middle, transparent);
		drawCornerAura(graphics, bounds.x + bounds.width, bounds.y + bounds.height,
			radius, center, middle, transparent);
	}

	private static void drawCornerAura(
		Graphics2D graphics, int x, int y, int radius, Color center, Color middle, Color transparent)
	{
		graphics.setPaint(new RadialGradientPaint(
			new Point2D.Double(x, y), radius,
			new float[]{0f, 0.38f, 1f},
			new Color[]{center, middle, transparent}));
		graphics.fillRect(x - radius, y - radius, radius * 2, radius * 2);
	}

	private double getPulseMultiplier()
	{
		if (!config.criticalPulse()
			|| (!plugin.isHitpointsCritical() && !plugin.isPrayerCritical() && !plugin.isIdleCritical()))
		{
			return 1;
		}

		double phase = (System.currentTimeMillis() % (long) PULSE_PERIOD_MILLIS)
			/ PULSE_PERIOD_MILLIS * Math.PI * 2;
		return 0.82 + 0.18 * ((Math.sin(phase) + 1) / 2);
	}

	private static Color blendColors(
		Color first, double firstWeight, Color second, double secondWeight, Color third, double thirdWeight)
	{
		double total = firstWeight + secondWeight + thirdWeight;
		if (total <= 0)
		{
			return first;
		}

		double firstRatio = firstWeight / total;
		double secondRatio = secondWeight / total;
		double thirdRatio = thirdWeight / total;
		return new Color(
			(int) Math.round(first.getRed() * firstRatio + second.getRed() * secondRatio + third.getRed() * thirdRatio),
			(int) Math.round(first.getGreen() * firstRatio + second.getGreen() * secondRatio + third.getGreen() * thirdRatio),
			(int) Math.round(first.getBlue() * firstRatio + second.getBlue() * secondRatio + third.getBlue() * thirdRatio),
			(int) Math.round(first.getAlpha() * firstRatio + second.getAlpha() * secondRatio + third.getAlpha() * thirdRatio));
	}

	private static void drawEdgeWarning(Graphics2D graphics, Rectangle bounds, int depth, Color edge)
	{
		Paint oldPaint = graphics.getPaint();
		Color transparent = new Color(edge.getRed(), edge.getGreen(), edge.getBlue(), 0);
		int left = bounds.x;
		int top = bounds.y;
		int right = bounds.x + bounds.width;
		int bottom = bounds.y + bounds.height;

		graphics.setPaint(new GradientPaint(left, top, edge, left + depth, top, transparent));
		graphics.fillRect(left, top, depth, bounds.height);
		graphics.setPaint(new GradientPaint(right, top, edge, right - depth, top, transparent));
		graphics.fillRect(right - depth, top, depth, bounds.height);
		graphics.setPaint(new GradientPaint(left, top, edge, left, top + depth, transparent));
		graphics.fillRect(left, top, bounds.width, depth);
		graphics.setPaint(new GradientPaint(left, bottom, edge, left, bottom - depth, transparent));
		graphics.fillRect(left, bottom - depth, bounds.width, depth);

		graphics.setPaint(oldPaint);
	}

	private static int clampAlpha(int alpha)
	{
		return Math.max(0, Math.min(255, alpha));
	}
}

