import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
	name = "Better Notifications",
	description = "Shooter-style edge warning for low hitpoints and prayer",
	tags = {"hitpoints", "health", "prayer", "notification", "overlay"}
)
public class BetterNotificationsPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private BetterNotificationsConfig config;

	@Inject
	private BetterNotificationsOverlay overlay;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private Notifier notifier;

	private double hitpointsDanger;

	private double prayerDanger;
	private double idleDanger;

	private boolean hitpointsCritical;

	private boolean prayerCritical;
	private boolean idleCritical;

	private boolean hitpointsNotificationArmed = true;
	private boolean prayerNotificationArmed = true;
	private boolean idleNotificationArmed = true;
	private long hitpointsCriticalSince;
	private long prayerCriticalSince;
	private long idleSince;
	private WorldPoint lastPosition;
	private long lastMousePressedMillis;
	private int lastKeyboardIdleTicks = -1;

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
		resetState();
		log.debug("Better Notifications started");
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		resetState();
		overlay.reset();
		log.debug("Better Notifications stopped");
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			resetState();
			return;
		}

		updateHitpoints();
		updatePrayer();
		updateIdle();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() != GameState.LOGGED_IN)
		{
			resetState();
		}
	}

	double getHitpointsDanger()
	{
		return config.previewMode() == PreviewMode.HITPOINTS ? getPreviewDanger() : hitpointsDanger;
	}

	double getPrayerDanger()
	{
		return config.previewMode() == PreviewMode.PRAYER ? getPreviewDanger() : prayerDanger;
	}

	double getIdleDanger()
	{
		return config.previewMode() == PreviewMode.IDLE ? getPreviewDanger() : idleDanger;
	}

	boolean isHitpointsCritical()
	{
		return config.previewMode() == PreviewMode.HITPOINTS
			? getPreviewDanger() >= 1
			: hitpointsCritical;
	}

	boolean isPrayerCritical()
	{
		return config.previewMode() == PreviewMode.PRAYER
			? getPreviewDanger() >= 1
			: prayerCritical;
	}

	boolean isIdleCritical()
	{
		return config.previewMode() == PreviewMode.IDLE
			? getPreviewDanger() >= 1
			: idleCritical;
	}

	private double getPreviewDanger()
	{
		return Math.max(1, Math.min(100, config.previewIntensityPercent())) / 100.0;
	}

	private void updateHitpoints()
	{
		if (!config.hitpointsEnabled())
		{
			hitpointsDanger = 0;
			hitpointsCritical = false;
			hitpointsNotificationArmed = true;
			hitpointsCriticalSince = 0;
			return;
		}

		int current = client.getBoostedSkillLevel(Skill.HITPOINTS);
		int maximum = client.getRealSkillLevel(Skill.HITPOINTS);
		int criticalAmount = DangerLevel.effectiveCriticalAmount(
			config.hitpointsWarningAmount(), config.hitpointsCriticalAmount());
		hitpointsDanger = DangerLevel.calculate(
			current, maximum, config.hitpointsWarningAmount(), criticalAmount);
		hitpointsCritical = DangerLevel.isCritical(current, maximum, criticalAmount);

		if (hitpointsCritical)
		{
			if (hitpointsCriticalSince == 0)
			{
				hitpointsCriticalSince = System.nanoTime();
			}
		}

		if (maximum > 0 && current >= 0
			&& current <= config.hitpointsNotificationAmount()
			&& hitpointsNotificationArmed)
		{
			hitpointsNotificationArmed = false;
			if (config.hitpointsNotification())
			{
				notifier.notify("Hitpoints are low: " + current + " remaining");
			}
		}
		else if (maximum > 0
			&& current > Math.max(config.hitpointsWarningAmount(), config.hitpointsNotificationAmount()))
		{
			hitpointsNotificationArmed = true;
		}

		if (maximum > 0 && current > config.hitpointsWarningAmount())
		{
			hitpointsCriticalSince = 0;
		}

		if (config.hitpointsAutoHide()
			&& hasAutoHideElapsed(hitpointsCriticalSince, config.hitpointsAutoHideSeconds()))
		{
			hitpointsDanger = 0;
		}
	}

	private void updatePrayer()
	{
		if (!config.prayerEnabled())
		{
			prayerDanger = 0;
			prayerCritical = false;
			prayerNotificationArmed = true;
			prayerCriticalSince = 0;
			return;
		}

		int current = client.getBoostedSkillLevel(Skill.PRAYER);
		int maximum = client.getRealSkillLevel(Skill.PRAYER);
		int criticalAmount = DangerLevel.effectiveCriticalAmount(
			config.prayerWarningAmount(), config.prayerCriticalAmount());
		prayerDanger = DangerLevel.calculate(
			current, maximum, config.prayerWarningAmount(), criticalAmount);
		prayerCritical = DangerLevel.isCritical(current, maximum, criticalAmount);

		if (prayerCritical)
		{
			if (prayerCriticalSince == 0)
			{
				prayerCriticalSince = System.nanoTime();
			}
		}

		if (maximum > 0 && current >= 0
			&& current <= config.prayerNotificationAmount()
			&& prayerNotificationArmed)
		{
			prayerNotificationArmed = false;
			if (config.prayerNotification())
			{
				notifier.notify("Prayer is low: " + current + " remaining");
			}
		}
		else if (maximum > 0
			&& current > Math.max(config.prayerWarningAmount(), config.prayerNotificationAmount()))
		{
			prayerNotificationArmed = true;
		}

		if (maximum > 0 && current > config.prayerWarningAmount())
		{
			prayerCriticalSince = 0;
		}

		if (config.prayerAutoHide()
			&& hasAutoHideElapsed(prayerCriticalSince, config.prayerAutoHideSeconds()))
		{
			prayerDanger = 0;
		}
	}

	private static boolean hasAutoHideElapsed(long criticalSince, int delaySeconds)
	{
		return criticalSince != 0
			&& System.nanoTime() - criticalSince >= delaySeconds * 1_000_000_000L;
	}

	private void updateIdle()
	{
		if (!config.idleEnabled() || config.previewMode() != PreviewMode.OFF)
		{
			resetIdleState();
			return;
		}

		Player localPlayer = client.getLocalPlayer();
		if (localPlayer == null)
		{
			resetIdleState();
			return;
		}

		WorldPoint position = localPlayer.getWorldLocation();
		boolean moved = lastPosition != null && !lastPosition.equals(position);
		lastPosition = position;
		long mousePressedMillis = client.getMouseLastPressedMillis();
		int keyboardIdleTicks = client.getKeyboardIdleTicks();
		boolean inputActivity = (lastMousePressedMillis != 0
			&& mousePressedMillis > lastMousePressedMillis)
			|| (lastKeyboardIdleTicks >= 0
				&& keyboardIdleTicks < lastKeyboardIdleTicks);
		lastMousePressedMillis = mousePressedMillis;
		lastKeyboardIdleTicks = keyboardIdleTicks;

		if (inputActivity || moved || localPlayer.getAnimation() != -1)
		{
			idleSince = 0;
			idleDanger = 0;
			idleCritical = false;
			idleNotificationArmed = true;
			return;
		}

		if (idleSince == 0)
		{
			idleSince = System.nanoTime();
		}

		long elapsedNanos = System.nanoTime() - idleSince;
		int criticalSeconds = DangerLevel.effectiveCriticalSeconds(
			config.idleNotificationSeconds(), config.idleCriticalSeconds());
		idleDanger = DangerLevel.calculateElapsed(
			elapsedNanos, config.idleNotificationSeconds(), criticalSeconds);
		idleCritical = elapsedNanos >= criticalSeconds * 1_000_000_000L;

		if (idleCritical && idleNotificationArmed)
		{
			idleNotificationArmed = false;
			if (config.idleNotification())
			{
				notifier.notify("You have been idle for " + criticalSeconds + " seconds");
			}
		}

		if (config.idleAutoHide()
			&& elapsedNanos >= (criticalSeconds + config.idleAutoHideSeconds()) * 1_000_000_000L)
		{
			idleDanger = 0;
		}
	}

	private void resetState()
	{
		hitpointsDanger = 0;
		prayerDanger = 0;
		idleDanger = 0;
		hitpointsCritical = false;
		prayerCritical = false;
		idleCritical = false;
		hitpointsNotificationArmed = true;
		prayerNotificationArmed = true;
		idleNotificationArmed = true;
		hitpointsCriticalSince = 0;
		prayerCriticalSince = 0;
		idleSince = 0;
		lastPosition = null;
		lastMousePressedMillis = 0;
		lastKeyboardIdleTicks = -1;
	}

	private void resetIdleState()
	{
		idleDanger = 0;
		idleCritical = false;
		idleSince = 0;
		idleNotificationArmed = true;
		lastPosition = null;
		lastMousePressedMillis = 0;
		lastKeyboardIdleTicks = -1;
	}

	@Provides
	BetterNotificationsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BetterNotificationsConfig.class);
	}
}
